@startuml

class Customer {
  + name : string
  + address : string
}

class Account {
  + balance : double
}

class SavingsAccount extends Account {
  + interestRate : float
}

class InvestmentAccount extends Account {}

class StockOrder {
  + ticker : string
  + quantity : int
  + price : double
  + commission : double
}

class Stock {
  + ticker : string
}

Customer "1" -- "*" Account
Account "1" -- "*" StockOrder
StockOrder "*" -- "1" Stock

@enduml

